String encrypt(String s) {
  const String alphabet = 'abcdefghijklmnopqrstuvwxyz';
  String result = '';
  for (int i = 0; i < s.length; i++) {
    String c = s[i];
    if (alphabet.contains(c)) {
      int idx = alphabet.indexOf(c);
      int newIdx = (idx + 4) % 26;
      result = result + alphabet[newIdx];
    } else {
      result = result + c;
    }
  }
  return result;
}
