int minSubArraySum(List<int> nums) {
  int maxSum = 0;
  int currentSum = 0;

  for (var num in nums) {
    currentSum = currentSum + (-num);
    if (currentSum < 0) {
      currentSum = 0;
    }
    if (currentSum > maxSum) {
      maxSum = currentSum;
    }
  }

  if (maxSum == 0) {
    return -nums.reduce((a, b) => a + b);
  }

  return -maxSum;
}
